import{_ as e,o as t,c as r,ag as i}from"./chunks/framework.DGzMGr_a.js";const u=JSON.parse('{"title":"制作人专访：赛季制、百人副本与多元宇宙","description":"制作人 YU 深度解析 RO3 核心玩法设计理念","frontmatter":{"title":"制作人专访：赛季制、百人副本与多元宇宙","description":"制作人 YU 深度解析 RO3 核心玩法设计理念"},"headers":[],"relativePath":"news/interview-202601.md","filePath":"news/interview-202601.md","lastUpdated":1779113336000}'),o={name:"news/interview-202601.md"};function l(n,a,h,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="制作人专访-赛季制、百人副本与多元宇宙" tabindex="-1">制作人专访：赛季制、百人副本与多元宇宙 <a class="header-anchor" href="#制作人专访-赛季制、百人副本与多元宇宙" aria-label="Permalink to &quot;制作人专访：赛季制、百人副本与多元宇宙&quot;">​</a></h1><p>日期：2026-01-29</p><p>台媒独家专访 RO3 制作人 YU，揭秘正统续作如何延续 20 年经典。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><h3 id="赛季制" tabindex="-1">赛季制 <a class="header-anchor" href="#赛季制" aria-label="Permalink to &quot;赛季制&quot;">​</a></h3><p>每个赛季 3-4 个月，推出新的职业流派。玩家可随时加入，不用担心差距过大。未来将举办投票让玩家选出想复刻的赛季。</p><h3 id="百人副本" tabindex="-1">百人副本 <a class="header-anchor" href="#百人副本" aria-label="Permalink to &quot;百人副本&quot;">​</a></h3><p>游戏中存在一只巨大的「鲲」，对应的是百人副本，核心概念是 Party Game，大家一起娱乐。</p><h3 id="十人副本" tabindex="-1">十人副本 <a class="header-anchor" href="#十人副本" aria-label="Permalink to &quot;十人副本&quot;">​</a></h3><p>不追求输出，更强调互动性——玩家与玩家、玩家与场景、玩家与 Boss 之间的互动。</p><h3 id="gvg-攻城战" tabindex="-1">GVG 攻城战 <a class="header-anchor" href="#gvg-攻城战" aria-label="Permalink to &quot;GVG 攻城战&quot;">​</a></h3><ul><li>大幅削弱「一人攻城」概念</li><li>需要大量玩家操作炮台与巨型机甲</li><li>包含攻城车、云梯、炮台等战略元素</li></ul><h3 id="多元宇宙设定" tabindex="-1">多元宇宙设定 <a class="header-anchor" href="#多元宇宙设定" aria-label="Permalink to &quot;多元宇宙设定&quot;">​</a></h3><p>新角色「布拉吉丝」将带领玩家穿越平行宇宙，每个世界拥有独特文明风貌与挑战。</p><h3 id="自动战斗" tabindex="-1">自动战斗 <a class="header-anchor" href="#自动战斗" aria-label="Permalink to &quot;自动战斗&quot;">​</a></h3><p>自动战斗效率约为手动的 70%-80%，解决日常练级负担。</p><h3 id="pc-优先" tabindex="-1">PC 优先 <a class="header-anchor" href="#pc-优先" aria-label="Permalink to &quot;PC 优先&quot;">​</a></h3><p>游戏原生为 PC 打造，但会同步推出移动端。</p>',18)])])}const _=e(o,[["render",l]]);export{u as __pageData,_ as default};
